119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
122	        List<String> missingFields = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
130	        if (isBlank(normalizedAddress)) {
131	            missingFields.add("address");
132	        }
133	        if (isBlank(ownerFieldsDto.getCity())) {
134	            missingFields.add("city");
135	        }
136	        if (isBlank(ownerFieldsDto.getTelephone())) {
137	            missingFields.add("telephone");
138	        }
139	        if (!missingFields.isEmpty()) {
140	            throw new MissingOwnerFieldsException(missingFields);
141	        }
142	        ownerFieldsDto.setAddress(normalizedAddress);
143	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
144	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
145	            .filter(existing -> lastName.equals(normalizeHousehold(existing.getLastName()))
146	                && normalizedAddress.equals(normalizeAddress(existing.getAddress())))
147	            .toList();
148	        String householdId = null;
149	        if (!householdMembers.isEmpty()) {
150	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
151	                throw new DuplicateHouseholdException(
152	                    "an owner with the same last name and address already exists");
153	            }
154	            // Joining an existing household: share a stable identifier with every member,
155	            // backfilling any members created before the household was formed.
156	            householdId = householdId(lastName, normalizedAddress);
157	            for (Owner member : householdMembers) {
158	                if (!householdId.equals(member.getHouseholdId())) {
159	                    member.setHouseholdId(householdId);
160	                    this.clinicService.saveOwner(member);
161	                }
162	            }
163	        }
164	        String telephone = toE164(ownerFieldsDto.getTelephone());
165	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
166	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
167	        if (telephoneInUse) {
168	            throw new DuplicateTelephoneException(
169	                "an owner with the same E.164 telephone already exists");
170	        }
171	        ownerFieldsDto.setTelephone(telephone);
172	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
173	        HttpHeaders headers = new HttpHeaders();
174	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
175	        if (owner.getRegistrationDate() == null) {
176	            owner.setRegistrationDate(LocalDate.now());
177	        }
178	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
179	        owner.setHouseholdId(householdId);
180	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
181	        this.clinicService.saveOwner(owner);
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
