365	        return (int) this.clinicService.findAllOwners().stream()
366	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
367	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
368	            .count();
