373	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
374	     * national one, a single leading {@code '0'} is dropped, and the default country code
375	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'},
376	     * otherwise an {@link InvalidTelephoneException} is raised (reported to the client as 400).
377	     */
378	    private static String toE164(String telephone) {
379	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
380	        String digits;
381	        if (cleaned.startsWith("+")) {
382	            digits = cleaned.substring(1);
383	        } else {
384	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
385	            digits = "61" + national;
386	        }
387	        if (!digits.matches("[0-9]{8,15}")) {
388	            throw new InvalidTelephoneException(
389	                "telephone must form a valid E.164 number with 8 to 15 digits");
390	        }
