396	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
397	     * is raised (reported to the client as 400). A valid value is returned lower-cased so it is
398	     * stored and returned in canonical form.
399	     */
400	    private static String normalizeEmail(String email) {
